from bookings import Booking, load_bookings, ROWS
from lookup import bookings_for, has_hotel

KEY = ROWS[0][0]
COUNT = sum(1 for k, _ in ROWS if k == KEY)


def test_upper_case_with_spaces():
    assert len(bookings_for(list(load_bookings()), " " + KEY.upper() + " ")) == COUNT


def test_stored_value_not_tidy():
    data = [Booking("  Alpha", 1), Booking("beta", 2), Booking("ALPHA ", 3)]
    assert [x.nights for x in bookings_for(data, "alpha")] == [1, 3]


def test_exact():
    assert len(bookings_for(list(load_bookings()), KEY)) == COUNT


def test_no_match():
    assert bookings_for(list(load_bookings()), "zzz") == [] and not has_hotel(list(load_bookings()), "zzz")
